<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
interface Field { id:number; entity_type:string; key:string; label:string; type:string; is_required:boolean; is_active:boolean; sort_order:number; options:string[]|null }
const props=defineProps<{fields:Field[];entityTypes:{value:string;label:string}[];types:string[]}>();
const editing=ref<Field|null>(null),show=ref(false);
const form=useForm({entity_type:props.entityTypes[0]?.value??'',key:'',label:'',type:'text',is_required:false,is_active:true,sort_order:0,options:[] as string[]});
function openCreate(){editing.value=null;form.reset();form.entity_type=props.entityTypes[0]?.value??'';form.type='text';form.is_active=true;form.options=[];form.clearErrors();show.value=true}
function openEdit(f:Field){editing.value=f;Object.assign(form,{entity_type:f.entity_type,key:f.key,label:f.label,type:f.type,is_required:f.is_required,is_active:f.is_active,sort_order:f.sort_order,options:[...(f.options??[])]});form.clearErrors();show.value=true}
function close(){show.value=false;editing.value=null;form.reset();form.clearErrors()}
function submit(){const o={preserveScroll:true,onSuccess:close};editing.value?form.put(route('custom-fields.update',editing.value.id),o):form.post(route('custom-fields.store'),o)}
function remove(f:Field){if(confirm('آیا از حذف «'+f.label+'» مطمئن هستید؟'))useForm({}).delete(route('custom-fields.destroy',f.id),{preserveScroll:true})}
</script>
<template><Head title="فیلدهای سفارشی"/><AuthenticatedLayout>
<template #header><div class="flex items-center justify-between"><div><p class="text-xs text-teal-600">مدیریت سازمان</p><h2 class="mt-1 text-2xl font-bold text-slate-900">فیلدهای سفارشی</h2><p class="mt-1 text-sm text-slate-500">تعریف اطلاعات متغیر موجودیت‌های سازمانی</p></div><button class="rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-semibold text-white" @click="openCreate">+ فیلد جدید</button></div></template>
<div class="min-h-[calc(100vh-8rem)] bg-slate-50 py-6"><div class="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8"><section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="border-b p-5"><h3 class="font-bold">تعریف فیلدها</h3></div><div v-if="!props.fields.length" class="p-16 text-center text-sm text-slate-500">هنوز فیلدی تعریف نشده است.</div><div v-else class="overflow-x-auto"><table class="w-full min-w-[800px] text-right"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="p-4">عنوان</th><th class="p-4">کلید</th><th class="p-4">موجودیت</th><th class="p-4">نوع</th><th class="p-4">وضعیت</th><th class="p-4">عملیات</th></tr></thead><tbody class="divide-y"><tr v-for="f in props.fields" :key="f.id"><td class="p-4 font-semibold">{{f.label}}</td><td dir="ltr" class="p-4 text-sm text-slate-500">{{f.key}}</td><td class="p-4 text-sm">{{props.entityTypes.find(e=>e.value===f.entity_type)?.label??f.entity_type}}</td><td class="p-4 text-sm">{{f.type}}</td><td class="p-4"><span class="rounded-full px-2.5 py-1 text-xs" :class="f.is_active?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500'">{{f.is_active?'فعال':'غیرفعال'}}</span></td><td class="p-4"><button class="ml-2 rounded-lg border px-3 py-1.5 text-xs" @click="openEdit(f)">ویرایش</button><button class="rounded-lg border border-red-100 px-3 py-1.5 text-xs text-red-600" @click="remove(f)">حذف</button></td></tr></tbody></table></div></section></div></div>
<div v-if="show" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4"><div class="w-full max-w-2xl rounded-2xl bg-white p-6 shadow-2xl"><div class="flex justify-between border-b pb-4"><h3 class="text-lg font-bold">{{editing?'ویرایش فیلد':'ایجاد فیلد'}}</h3><button @click="close">×</button></div><form class="mt-5 space-y-4" @submit.prevent="submit"><div class="grid gap-4 md:grid-cols-2"><div><label class="text-sm font-semibold">موجودیت</label><select v-model="form.entity_type" class="mt-1 w-full rounded-xl border-slate-200"><option v-for="e in props.entityTypes" :key="e.value" :value="e.value">{{e.label}}</option></select></div><div><label class="text-sm font-semibold">کلید</label><input v-model="form.key" dir="ltr" class="mt-1 w-full rounded-xl border-slate-200"></div></div><div><label class="text-sm font-semibold">عنوان</label><input v-model="form.label" class="mt-1 w-full rounded-xl border-slate-200"></div><div class="grid gap-4 md:grid-cols-3"><div><label class="text-sm font-semibold">نوع</label><select v-model="form.type" class="mt-1 w-full rounded-xl border-slate-200"><option v-for="t in props.types" :key="t" :value="t">{{t}}</option></select></div><input v-model.number="form.sort_order" type="number" min="0" class="rounded-xl border-slate-200"><div class="flex items-center gap-3 text-sm"><label><input v-model="form.is_required" type="checkbox"> الزامی</label><label><input v-model="form.is_active" type="checkbox"> فعال</label></div></div><div v-if="form.type==='select'" class="rounded-xl border p-4"><div class="flex justify-between text-sm font-semibold"><span>گزینه‌ها</span><button type="button" class="text-teal-700" @click="form.options.push('')">+ افزودن</button></div><div v-for="(_,i) in form.options" :key="i" class="mt-2 flex gap-2"><input v-model="form.options[i]" class="flex-1 rounded-lg border-slate-200"><button type="button" @click="form.options.splice(i,1)">×</button></div></div><div class="flex justify-end gap-3 border-t pt-5"><button type="button" class="rounded-xl border px-4 py-2" @click="close">انصراف</button><button :disabled="form.processing" class="rounded-xl bg-slate-900 px-5 py-2 text-sm font-semibold text-white">ذخیره</button></div></form></div></div>
</AuthenticatedLayout></template>